import {WATER,waterWalkRects} from './water.js';
import {LOCAL_LIFT} from './local-lift-config.js';
import {TRANSPORT_POLICY} from './transport-policy.js';
const Q1_STORAGE=TRANSPORT_POLICY.qStorage;
import {SPRINGS,BIOS,ROTATION_BAY} from './infrastructure.js';
import {connectionCheck} from './biology.js';
import {BODIES,BY_ID,SIZES,LEVELS,DECK,LOWER_DECK,levelName,LANDING,SHAFT,LIFE_BOUNDS,placements,connections,reachable,localNavigation,portStates,portSegment,boundaryWalls,defaultDoors,emptyDockCells,storageFor,architectureRevision} from './architecture.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={pass:'#3c8a60',view:'#d29b35',blocked:'#a67565'};
const line=(a,b,c='#647263',w=.12,dash='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${c}" stroke-width="${w}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
const onMapFloor=(sim,y)=>Math.abs((sim.owner==='CP1'?sim.positions.CP1.y:sim.player.y)-y)<.1;
function generateFloorSVG(sim,level,{phase=null,selected='R1',path=null,scope=sim.mapScope??'all',drawPlayer=true,drawBiology=true}={}){const planned=!!phase,state=phase??sim.phase,e=sim.experiment,doors=planned?defaultDoors():sim.doors,pos=planned?placements(state,e):sim.positions,links=planned?connections(state,e,doors):sim.liveConnections,ports=planned?portStates(state,e,doors):sim.livePorts,seen=planned?reachable(state,e,doors):sim.liveReachable,y=LEVELS[level];let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${scope==='remote'?'90 -1 31 46':scope==='main'?'-7.4 -10 112 56':'-7.4 -10 159 79'}" role="img" aria-label="${levelName(y)} ${state} 4方向・内部通路平面図"><defs><pattern id="well${level}" width="1" height="1" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="1" height="1" fill="#d4dacd"/><line x1="0" y1="0" x2="0" y2="1" stroke="#b7c3ac" stroke-width=".1"/></pattern><pattern id="iso${level}" width=".8" height=".8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2=".8" stroke="#aa7043" stroke-width=".15"/></pattern></defs><rect x="0" y="0" width="${LIFE_BOUNDS.w}" height="42" fill="url(#well${level})" stroke="#93aa86" stroke-width=".12"/><rect x="${SHAFT.x}" y="${SHAFT.z}" width="${SHAFT.w}" height="${SHAFT.d}" fill="#9caf99" stroke="#597555" stroke-width=".2"/><text x="-4.6" y="4.4" text-anchor="middle" font-size="1.1" fill="#3c5839">EV</text><rect x="-2.4" y="2" width="2" height="4" fill="#c0cbb5"/>`;
 if(LOCAL_LIFT.levels.includes(y)){const q=LOCAL_LIFT.shaft;s+=`<g data-fixed-lift="housing-lift"><rect x="${q.x}" y="${q.z}" width="${q.w}" height="${q.d}" fill="#9caf99" stroke="#597555" stroke-width=".2"/><rect x="${LOCAL_LIFT.offset.x+LANDING.x}" y="${LOCAL_LIFT.offset.z+LANDING.z}" width="2" height="4" fill="#c0cbb5"/><text x="${q.x+2.2}" y="${q.z+2.4}" text-anchor="middle" font-size=".8" fill="#3c5839">居住EV</text></g>`;}
 for(const c of links)if(c.level===level&&c.status!=='blocked'){const q=c.bridge;s+=`<rect x="${q.x}" y="${q.z}" width="${q.w}" height="${q.d}" fill="${colors[c.status]}" fill-opacity=".6"/>`;}
 for(const b of BODIES){if(scope==='main'&&b.remote)continue;const p=pos[b.id];if(Math.abs(p.y-y)>.1)continue;const nav=localNavigation(b,doors);s+=`<g data-id="${b.id}" transform="translate(${p.x} ${p.z}) rotate(${p.angle??0} 4 4)">`;for(const[i,[cx,cz]]of b.cells.entries())s+=`<rect x="${cx*8}" y="${cz*8}" width="8" height="8" fill="${b.color}" stroke="${selected===b.id?'#354f43':'#dce3d3'}" stroke-width="${selected===b.id?.23:.11}"/><text x="${cx*8+.3}" y="${cz*8+7.55}" font-size=".65" fill="#334f42">${b.id}.${i+1}</text>`;for(const o of b.solids)s+=`<rect x="${o.x}" y="${o.z}" width="${o.w}" height="${o.d}" fill="#67786a" opacity=".75"/>`;for(const o of b.furniture.filter(r=>!(r.floor>0)))s+=`<rect x="${o.x}" y="${o.z}" width="${o.w}" height="${o.d}" fill="#6f755a" opacity=".38"/>`;for(const l of[...boundaryWalls(b),...b.walls.filter(l=>!(l.floor>0))])s+=line(l.a,l.b,'#496150',.12);for(const d of b.doors.filter(d=>!(d.floor>0)))s+=line(d.a,d.b,(doors[d.id]??d.open)?'#e4ebd7':'#9b6c56',.2);
  for(let z=0;z<nav.nz;z++){let start=-1;for(let x=0;x<=nav.nx;x++){const label=x<nav.nx?nav.labels[z*nav.nx+x]:-1,unseen=label>=0&&!seen.has(`${b.id}/${label}`);if(unseen&&start<0)start=x;if(!unseen&&start>=0){s+=`<rect x="${start*nav.step}" y="${z*nav.step}" width="${(x-start)*nav.step}" height="${nav.step}" fill="url(#iso${level})"/>`;start=-1;}}}
  for(const p0 of b.ports){const st=ports.find(p=>p.key===`${b.id}:${p0.id}`);const base=portSegment(b,p0);s+=line(base.a,base.b,colors.blocked,.28);for(const o of st?.openings??[]){const l=portSegment(b,{...p0,a:o.a,b:o.b});s+=line(l.a,l.b,colors[o.status],.3);}if(selected===b.id){const l=portSegment(b,p0,.8);s+=`<text x="${(l.a[0]+l.b[0])/2}" y="${(l.a[1]+l.b[1])/2}" text-anchor="middle" font-size=".6" fill="#304b3d">${p0.id}</text>`;}}
  if(BIOS.some(n=>n.body===b.id))s+=`<circle cx="7.25" cy="4" r=".45" fill="#315f51"/><text x="5.6" y="5.9" font-size=".6">${BIOS.find(n=>n.body===b.id).id}</text>`;
  for(const l of b.labels.filter(l=>!(l.floor>0)))s+=`<text x="${l.x}" y="${l.z}" text-anchor="middle" font-size="${l.name.length>8?.52:.65}" fill="#304b3d">${esc(l.name)}</text>`;s+='</g>';
 }
 for(const q of WATER.filter(q=>q.y===y)){s+=`<g data-water="${q.id}"><rect x="${q.x}" y="${q.z}" width="${q.w}" height="${q.d}" fill="#438f99"/><text x="${q.x+1}" y="${q.z+2}" font-size=".8">${q.name} →</text>`;for(const r of waterWalkRects(q))s+=`<rect x="${r.x}" y="${r.z}" width="${r.w}" height="${r.d}" fill="#a4a598"/>`;s+='</g>';}
 for(const well of SPRINGS.filter(p=>p.y===y))s+=`<rect x="${well.x}" y="${well.z}" width="3" height="3" fill="#81a99b" stroke="#345e54" stroke-width=".2"/><text x="${well.x+1.5}" y="${well.z+1.9}" font-size=".8" text-anchor="middle">${well.id}</text>`;
 if(drawBiology)for(const bio of BIOS){const well=SPRINGS.find(p=>connectionCheck({...sim,positions:pos},bio,p).ok);if(well&&pos[bio.body].y===y){const c=connectionCheck({...sim,positions:pos},bio,well);const a=!planned&&sim.biology?.animals[bio.id],progress=a?.connection?.spring===well.id?a.progress:0,t=planned?1:progress;s+=line([c.from.x,c.from.z],[c.from.x+(c.to.x-c.from.x)*t,c.from.z+(c.to.z-c.from.z)*t],'#568c79',.25,planned?'.3 .2':'');}}
 for(const q of emptyDockCells(state,e).filter(q=>q.y===y))s+=`<text x="${q.x+4}" y="${q.z+4}" text-anchor="middle" font-size=".8" fill="#87967c">空欄</text>`;
 if(path?.ok&&Math.abs(path.start.y-y)<.1){const points=path.path.map(p=>`${p.x},${p.z}`).join(' '),color=state==='B'?'#267e5d':'#b48035';s+=`<polyline points="${points}" fill="none" stroke="${color}" stroke-width=".17" stroke-linejoin="round"/><circle cx="${path.start.x}" cy="${path.start.z}" r=".33" fill="${color}"/><circle cx="${path.goal.x}" cy="${path.goal.z}" r=".33" fill="${color}"/>`;}
 if(drawPlayer&&!planned&&onMapFloor(sim,y)){const p=sim.player;s+=`<circle cx="${p.x}" cy="${p.z}" r=".42" fill="#cc6045" stroke="#f7f7e9" stroke-width=".13"/>${line([p.x,p.z],[p.x+Math.sin(p.yaw)*1.3,p.z+Math.cos(p.yaw)*1.3],'#cc6045',.15)}`;}
 return s+`<text x="${LIFE_BOUNDS.w}" y="44" text-anchor="end" font-size=".75" fill="#7b8d72">N ↑ ／ 灰：床なし・茶：未到達通路</text></svg>`;}
export function deckSVG(sim){const e=sim.experiment,b=SIZES[e.size],stored=storageFor(e);let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="-7 -10 ${b.w+9} ${b.d+16}" role="img" aria-label="予備廊下と一時退避・搬送中の高さ別占有"><rect x="0" y="0" width="${b.w}" height="${b.d}" fill="#d9e1cf" stroke="#8ca280" stroke-width=".2"/><rect x="0" y="0" width="${LIFE_BOUNDS.w}" height="42" fill="none" stroke="#6d865f" stroke-width=".15" stroke-dasharray=".6 .4"/><rect x="${stored.x}" y="${stored.z}" width="8" height="8" fill="none" stroke="#aaa84f" stroke-width=".25" stroke-dasharray=".5 .3"/><text x="${stored.x+4}" y="${stored.z+1.1}" text-anchor="middle" font-size=".7" fill="#7d7e3d">C0 予備保管</text>`;s+=`<rect x="${Q1_STORAGE.x}" y="${Q1_STORAGE.z}" width="8" height="16" fill="none" stroke="#8c8e60" stroke-width=".25" stroke-dasharray=".5 .3"/><text x="${Q1_STORAGE.x+4}" y="${Q1_STORAGE.z+1.1}" text-anchor="middle" font-size=".7">Q1 保管 y−6.4</text>`;if(e.size!=='same')s+=`<rect x="25.6" y="17.2" width="16" height="16" fill="none" stroke="#b79a62" stroke-width=".18" stroke-dasharray=".6 .4"/><text x="33.6" y="31.8" text-anchor="middle" font-size=".7" fill="#9a7e48">H1 一時退避</text>`;for(let z=0;z<b.d;z+=8.4)s+=line([0,z],[b.w,z],'#b6c6ab',.08);for(let x=0;x<b.w;x+=8.4)s+=line([x,0],[x,b.d],'#b6c6ab',.08);
 if(sim.plan)for(const st of sim.plan.stages)for(const m of st.motions){const body=BY_ID[m.id],f={w:(Math.max(...body.cells.map(c=>c[0]))+1)*8,d:(Math.max(...body.cells.map(c=>c[1]))+1)*8};s+=line([m.from.x+f.w/2,m.from.z+f.d/2],[m.to.x+f.w/2,m.to.z+f.d/2],body.color,.12,'.5 .4');}const stage=sim.mode==='moving'?sim.plan?.stages[sim.stageIndex]:null;if(stage)for(const m of stage.motions)for(const[cx,cz]of BY_ID[m.id].cells)s+=`<rect x="${Math.min(m.from.x,m.to.x)+cx*8}" y="${Math.min(m.from.z,m.to.z)+cz*8}" width="${8+Math.abs(m.from.x-m.to.x)}" height="${8+Math.abs(m.from.z-m.to.z)}" fill="#d1aa47" fill-opacity=".2" stroke="#b58f36" stroke-width=".1"/>`;
 s+=`<circle cx="${ROTATION_BAY.x+4}" cy="${ROTATION_BAY.z+4}" r="${ROTATION_BAY.radius+.2}" fill="none" stroke="#a77f3e" stroke-width=".2" stroke-dasharray=".5 .3"/><text x="${ROTATION_BAY.x+4}" y="${ROTATION_BAY.z+11}" text-anchor="middle" font-size=".8">90° 回転包絡域</text>`;
 if(sim.plan)for(const r of sim.plan.reservations.filter(r=>r.rotation)){const q=r.rotation;s+=`<circle cx="${q.slot.x+4}" cy="${q.slot.z+4}" r="${q.radius+.2}" fill="none" stroke="#a77c39" stroke-width=".16"/><text x="${q.slot.x+4}" y="${q.slot.z+11}" text-anchor="middle" font-size=".65">${r.id} ${q.kind} y${q.slot.y} / ${q.reservedFrom.toFixed(1)}–${q.reservedTo.toFixed(1)}s</text>`;}
 for(const q of WATER)s+=`<g data-fixed-water="${q.id}"><rect x="${q.x}" y="${q.z}" width="${q.w}" height="${q.d}" fill="#438f99" fill-opacity=".35" stroke="#346778" stroke-width=".15"/><text x="${q.x+1}" y="${q.z+2}" font-size=".8">${q.id} 固定 y${q.y}</text></g>`;
 for(const well of SPRINGS)s+=`<rect x="${well.x}" y="${well.z}" width="3" height="3" fill="#719f8d"/><text x="${well.x+1.5}" y="${well.z+1.8}" font-size=".7" text-anchor="middle">${well.id}</text>`;
 for(const body of BODIES){const p=sim.positions[body.id];s+=`<g data-id="${body.id}" transform="translate(${p.x} ${p.z}) rotate(${p.angle??0} 4 4)" opacity="${[DECK,LOWER_DECK].some(y=>Math.abs(p.y-y)<.1)?1:.5}">`;for(const[cx,cz]of body.cells)s+=`<rect x="${cx*8+.08}" y="${cz*8+.08}" width="7.84" height="7.84" fill="${body.color}" stroke="#546d51" stroke-width=".12"/>`;s+=`<text x="4" y="3.5" text-anchor="middle" font-size="1.1" fill="#304b3d">${body.id}</text><text x="4" y="5" text-anchor="middle" font-size=".85" fill="#425b45">y ${p.y.toFixed(1)}m / ${Math.round(p.angle??0)}°</text></g>`;}
 return s+`<circle cx="${sim.player.x}" cy="${sim.player.z}" r=".42" fill="#cc6045"/><text x="${b.w/2}" y="${b.d+2.5}" text-anchor="middle" font-size=".9" fill="#637c59">${b.w} × ${b.d}m ／ 上部 +6.4m / 下部 −6.4m・高さ別平面投影</text><text x="${b.w/2}" y="${b.d+4.4}" text-anchor="middle" font-size=".7" fill="#809071">黄：現在区間の掃引。重なりの衝突は3Dで検査。</text></svg>`;}

export const mapCacheMetrics={hits:0,generated:0};
const mapCache=new Map(),routeIds=new WeakMap();let routeSerial=0;
export function clearMapCache(){mapCache.clear();}
export function floorMapParts(sim,level,options={}){const phase=options.phase??null,scope=options.scope??sim.mapScope??'all',route=options.path;if(route&&!routeIds.has(route))routeIds.set(route,++routeSerial);const key=JSON.stringify([architectureRevision,phase??sim.phase,sim.experiment.size,level,options.selected??'R1',scope,phase?'planned':sim.doors,phase?0:sim.shutter>.01,phase?null:sim.positions,route?routeIds.get(route):0]);let base=mapCache.get(key);if(base){mapCacheMetrics.hits++;}else{base=generateFloorSVG(sim,level,{...options,drawPlayer:false,drawBiology:!!phase});mapCache.set(key,base);mapCacheMetrics.generated++;if(mapCache.size>36)mapCache.delete(mapCache.keys().next().value);}let overlay='';if(!phase){const y=LEVELS[level],p=sim.player;if(onMapFloor(sim,y))overlay+=`<circle cx="${p.x}" cy="${p.z}" r=".42" fill="#cc6045" stroke="#f7f7e9" stroke-width=".13"/>`+line([p.x,p.z],[p.x+Math.sin(p.yaw)*1.3,p.z+Math.cos(p.yaw)*1.3],'#cc6045',.15);for(const b of BIOS){const a=sim.biology?.animals[b.id],c=a?.connection;if(c&&a.progress>0&&sim.positions[b.body].y===y)overlay+=line([c.from.x,c.from.z],[c.from.x+(c.to.x-c.from.x)*a.progress,c.from.z+(c.to.z-c.from.z)*a.progress],'#568c79',.25);}if(sim.owner==='CP1'&&onMapFloor(sim,y))overlay+=`<text x="${p.x+.6}" y="${p.z-.6}" font-size=".7" fill="#a94a35">内部+${(p.y-sim.positions.CP1.y).toFixed(1)}m</text>`;}return{key,base,overlay};}
export function floorSVG(sim,level,options={}){const p=floorMapParts(sim,level,options);return p.base.replace('</svg>','<g data-live-overlays>'+p.overlay+'</g></svg>');}
